export const CONTROL_PLANE_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n  <title>AD NŪTUM Control Plane</title>\n  <style>\n    :root {\n      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n      color: #0f172a;\n      background: #eef3f8;\n    }\n    * { box-sizing: border-box; }\n    body { margin: 0; min-height: 100vh; }\n    button, input, textarea { font: inherit; }\n    button { cursor: pointer; }\n    .shell { display: grid; grid-template-columns: 245px 1fr; min-height: 100vh; }\n    aside {\n      background: #07111f; color: white; padding: 28px 20px; display: flex; flex-direction: column;\n      position: sticky; top: 0; height: 100vh;\n    }\n    .brand { font-weight: 950; letter-spacing: .08em; font-size: 24px; }\n    .brand span { color: #ff8a00; }\n    .tagline { margin-top: 7px; color: #9fb0c5; font-size: 12px; line-height: 1.5; }\n    nav { margin-top: 36px; display: grid; gap: 8px; }\n    nav button {\n      text-align: left; width: 100%; background: transparent; color: #b9c7d8; border: 0; padding: 11px 12px;\n      border-radius: 10px; font-weight: 750;\n    }\n    nav button.active, nav button:hover { background: #132238; color: white; }\n    .aside-foot { margin-top: auto; border-top: 1px solid #20314a; padding-top: 18px; color: #8193a9; font-size: 11px; }\n    main { padding: 34px clamp(20px, 4vw, 56px) 70px; min-width: 0; }\n    .topbar { display: flex; justify-content: space-between; gap: 20px; align-items: flex-start; margin-bottom: 26px; }\n    h1 { margin: 0; font-size: clamp(30px, 4vw, 48px); letter-spacing: -.04em; }\n    .kicker { font-size: 12px; text-transform: uppercase; letter-spacing: .12em; font-weight: 900; color: #49617d; margin-bottom: 8px; }\n    .muted { color: #64748b; }\n    .demo-badge { background: #fff7e8; color: #9a5700; border: 1px solid #f2d7a5; padding: 9px 12px; border-radius: 999px; font-weight: 850; font-size: 12px; white-space: nowrap; }\n    .stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; margin-bottom: 20px; }\n    .stat, .card { background: white; border: 1px solid #dbe4ee; border-radius: 18px; box-shadow: 0 8px 24px rgba(15,23,42,.04); }\n    .stat { padding: 18px; }\n    .stat-label { color: #64748b; font-size: 12px; font-weight: 800; text-transform: uppercase; letter-spacing: .08em; }\n    .stat-value { font-size: 30px; font-weight: 950; margin-top: 6px; }\n    .grid { display: grid; grid-template-columns: 1.45fr .85fr; gap: 18px; }\n    .card { padding: 20px; min-width: 0; }\n    .card h2 { margin: 0 0 4px; font-size: 18px; }\n    .card-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 16px; }\n    .btn { border: 0; border-radius: 11px; padding: 10px 13px; font-weight: 850; background: #0d4de8; color: white; }\n    .btn.secondary { background: #e8eef7; color: #18314f; }\n    .btn.danger { background: #b42318; }\n    .btn.success { background: #087443; }\n    .btn.small { padding: 7px 9px; font-size: 12px; }\n    .list { display: grid; gap: 9px; }\n    .request {\n      border: 1px solid #e1e8f0; border-radius: 14px; padding: 14px; display: grid; grid-template-columns: 1fr auto;\n      gap: 8px 14px; align-items: center; background: #fbfdff;\n    }\n    .request:hover { border-color: #aec2db; }\n    .request-title { font-weight: 900; }\n    .request-meta { font-size: 12px; color: #64748b; margin-top: 4px; }\n    .pill { display: inline-flex; align-items: center; padding: 5px 8px; border-radius: 999px; font-size: 11px; font-weight: 900; text-transform: uppercase; letter-spacing: .06em; }\n    .pill.pending { background: #fff3d7; color: #8a5300; }\n    .pill.allowed, .pill.approved { background: #dff6e9; color: #087443; }\n    .pill.denied, .pill.rejected { background: #fde8e7; color: #a12b25; }\n    .form-grid { display: grid; gap: 12px; }\n    label { font-size: 12px; font-weight: 850; color: #44546a; }\n    input, textarea {\n      width: 100%; border: 1px solid #cfd9e6; background: white; border-radius: 11px; padding: 10px 12px; margin-top: 6px;\n      outline: none;\n    }\n    input:focus, textarea:focus { border-color: #4b7cff; box-shadow: 0 0 0 3px rgba(75,124,255,.12); }\n    .split { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n    .timeline { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }\n    .timeline li { padding: 10px 12px; border-left: 3px solid #b7c7da; background: #f7faff; border-radius: 7px; font-size: 13px; }\n    .timeline strong { display: block; }\n    .empty { color: #7b8ca1; padding: 22px 0; text-align: center; }\n    .hidden { display: none !important; }\n    .modal-wrap {\n      position: fixed; inset: 0; background: rgba(4,12,24,.68); display: grid; place-items: center; padding: 20px; z-index: 20;\n    }\n    .modal { width: min(540px, 100%); background: white; border-radius: 20px; padding: 24px; box-shadow: 0 24px 70px rgba(0,0,0,.25); }\n    .modal h2 { margin-top: 0; }\n    .notice { font-size: 12px; line-height: 1.55; background: #f6f8fb; border: 1px solid #dce5ef; padding: 12px; border-radius: 11px; margin: 14px 0; color: #52657a; }\n    .view { display: none; }\n    .view.active { display: block; }\n    .error { color: #b42318; font-size: 12px; margin-top: 8px; white-space: pre-wrap; }\n    .codebox { background:#07111f; color:#d9e6f6; border-radius:12px; padding:14px; font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:12px; line-height:1.55; overflow:auto; white-space:pre-wrap; }\n    .key-row { border:1px solid #e1e8f0; border-radius:14px; padding:14px; display:grid; grid-template-columns:1fr auto; gap:10px; align-items:center; background:#fbfdff; }\n    .secret-reveal { background:#fff7e8; border:1px solid #f1d59e; border-radius:12px; padding:14px; margin-top:14px; }\n    .secret-value { font-family:ui-monospace,SFMono-Regular,Menlo,monospace; word-break:break-all; font-weight:800; }\n    @media (max-width: 920px) {\n      .shell { grid-template-columns: 1fr; }\n      aside { position: static; height: auto; }\n      nav { grid-template-columns: repeat(4, 1fr); margin-top: 20px; }\n      .aside-foot { display: none; }\n      .stats { grid-template-columns: 1fr 1fr; }\n      .grid { grid-template-columns: 1fr; }\n    }\n    @media (max-width: 560px) {\n      nav { grid-template-columns: 1fr 1fr; }\n      .stats { grid-template-columns: 1fr 1fr; }\n      .topbar { flex-direction: column; }\n    }\n  </style>\n</head>\n<body>\n<div class=\"shell\">\n  <aside>\n    <div class=\"brand\">AD <span>NŪTUM</span></div>\n    <div class=\"tagline\">Authorization infrastructure for AI agents.</div>\n    <nav>\n      <button data-view=\"overview\" class=\"active\">Overview</button>\n      <button data-view=\"requests\">Requests</button>\n      <button data-view=\"agents\">Agents</button>\n      <button data-view=\"policy\">Policy</button>\n      <button data-view=\"receipts\">Receipts</button>\n      <button data-view=\"developer\">Developer</button>\n    </nav>\n    <div class=\"aside-foot\">v1.3 Control Plane<br>Reasoning is not authority.</div>\n  </aside>\n\n  <main>\n    <div class=\"topbar\">\n      <div>\n        <div class=\"kicker\">Control Plane</div>\n        <h1 id=\"pageTitle\">Authorization overview</h1>\n        <div class=\"muted\" id=\"pageSub\">See what agents asked to do, what policy decided, and where human judgment entered.</div>\n      </div>\n      <div class=\"demo-badge\">Demo environment · no real money moves</div>\n    </div>\n\n    <section id=\"overview\" class=\"view active\">\n      <div class=\"stats\">\n        <div class=\"stat\"><div class=\"stat-label\">Requests</div><div class=\"stat-value\" id=\"statRequests\">—</div></div>\n        <div class=\"stat\"><div class=\"stat-label\">Awaiting human</div><div class=\"stat-value\" id=\"statPending\">—</div></div>\n        <div class=\"stat\"><div class=\"stat-label\">Approved</div><div class=\"stat-value\" id=\"statApproved\">—</div></div>\n        <div class=\"stat\"><div class=\"stat-label\">Agents</div><div class=\"stat-value\" id=\"statAgents\">—</div></div>\n      </div>\n\n      <div class=\"grid\">\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <div><h2>Recent authorization requests</h2><div class=\"muted\">Newest first</div></div>\n            <button class=\"btn secondary small\" id=\"refreshBtn\">Refresh</button>\n          </div>\n          <div id=\"recentRequests\" class=\"list\"><div class=\"empty\">Loading…</div></div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-head\"><div><h2>Authority Lab</h2><div class=\"muted\">Test different kinds of agent authority against one engine.</div></div></div>\n          <div class=\"form-grid\">\n            <label>Action\n              <select id=\"testAction\" style=\"width:100%;margin-top:6px;padding:10px 12px;border:1px solid #cfd9e6;border-radius:11px;background:white\">\n                <option value=\"refund_customer\">Refund customer</option>\n                <option value=\"increase_ad_budget\">Increase ad budget</option>\n                <option value=\"pay_invoice\">Pay invoice</option>\n                <option value=\"publish_content\">Publish content</option>\n                <option value=\"deploy_production\">Deploy production</option>\n                <option value=\"delete_record\">Delete record</option>\n              </select>\n            </label>\n            <label>Agent<input id=\"testAgent\" value=\"finance-agent\" /></label>\n            <label id=\"amountField\">Amount<input id=\"testAmount\" type=\"number\" value=\"4800\" min=\"1\" /></label>\n            <label id=\"subjectField\"><span id=\"subjectLabel\">Customer</span><input id=\"testSubject\" value=\"ABC Manufacturing\" /></label>\n            <label id=\"vendorField\" class=\"hidden\"><input id=\"testVendorApproved\" type=\"checkbox\" style=\"width:auto;margin-right:8px\" /> Vendor is already approved</label>\n            <label id=\"sensitiveField\" class=\"hidden\"><input id=\"testSensitive\" type=\"checkbox\" style=\"width:auto;margin-right:8px\" /> Content is sensitive</label>\n            <label id=\"scopeField\" class=\"hidden\">Data scope\n              <select id=\"testScope\" style=\"width:100%;margin-top:6px;padding:10px 12px;border:1px solid #cfd9e6;border-radius:11px;background:white\">\n                <option value=\"development\">Development</option>\n                <option value=\"staging\">Staging</option>\n                <option value=\"production\">Production</option>\n              </select>\n            </label>\n            <label>Reason / context<textarea id=\"testReason\" rows=\"3\">Duplicate payment detected</textarea></label>\n            <button class=\"btn\" id=\"createRequestBtn\">Ask for authorization</button>\n            <div class=\"error\" id=\"createError\"></div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"requests\" class=\"view\">\n      <div class=\"card\">\n        <div class=\"card-head\"><div><h2>Authorization requests</h2><div class=\"muted\">Open a request to inspect its evidence and audit trail.</div></div></div>\n        <div id=\"allRequests\" class=\"list\"><div class=\"empty\">Loading…</div></div>\n      </div>\n    </section>\n\n    <section id=\"agents\" class=\"view\">\n      <div class=\"grid\">\n        <div class=\"card\">\n          <div class=\"card-head\"><div><h2>Registered agents</h2><div class=\"muted\">Agent identities known to this demo project.</div></div></div>\n          <div id=\"agentList\" class=\"list\"><div class=\"empty\">Loading…</div></div>\n        </div>\n        <div class=\"card\">\n          <div class=\"card-head\"><div><h2>Add agent</h2><div class=\"muted\">Create a stable external identity.</div></div></div>\n          <div class=\"form-grid\">\n            <label>External key<input id=\"agentKey\" placeholder=\"support-agent\" /></label>\n            <label>Display name<input id=\"agentName\" placeholder=\"Customer Support Agent\" /></label>\n            <button class=\"btn\" id=\"addAgentBtn\">Add agent</button>\n            <div class=\"error\" id=\"agentError\"></div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"policy\" class=\"view\">\n      <div class=\"card\" style=\"max-width:760px\">\n        <div class=\"card-head\"><div><h2>Refund authority policy</h2><div class=\"muted\">The live thresholds used by <code>refund_customer</code>.</div></div></div>\n        <div class=\"notice\">This is deliberately narrow. v0.3 proves that policy can be changed in the control plane and enforced by the live authorization API.</div>\n        <div class=\"split\">\n          <label>Auto-allow below $<input id=\"automaticBelow\" type=\"number\" min=\"1\" /></label>\n          <label>Manager approval through $<input id=\"managerThrough\" type=\"number\" min=\"2\" /></label>\n        </div>\n        <div class=\"notice\">Amounts at or above the first threshold require manager approval until the second threshold. Amounts above the second threshold require owner approval.</div>\n        <button class=\"btn\" id=\"savePolicyBtn\">Save policy</button>\n        <div class=\"error\" id=\"policyError\"></div>\n      </div>\n    </section>\n    <section id=\"receipts\" class=\"view\">\n      <div class=\"grid\">\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <div>\n              <h2>Authority receipts</h2>\n              <div class=\"muted\">Durable grants that prove an agent actually had authority.</div>\n            </div>\n            <button class=\"btn secondary small\" id=\"refreshReceiptsBtn\">Refresh</button>\n          </div>\n          <div id=\"receiptList\" class=\"list\"><div class=\"empty\">Loading…</div></div>\n        </div>\n\n        <div style=\"display:grid;gap:18px;align-content:start\">\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div>\n                <h2>Verify authority</h2>\n                <div class=\"muted\">Check whether a receipt is valid for an exact execution right now.</div>\n              </div>\n            </div>\n            <div class=\"form-grid\">\n              <label>Receipt\n                <select id=\"verifyReceiptId\" style=\"width:100%;margin-top:6px;padding:10px 12px;border:1px solid #cfd9e6;border-radius:11px;background:white\"></select>\n              </label>\n              <label>Agent<input id=\"verifyAgent\" value=\"assistant-agent\" /></label>\n              <label>Action<input id=\"verifyAction\" value=\"increase_ad_budget\" /></label>\n              <label>Amount<input id=\"verifyAmount\" type=\"number\" value=\"75\" min=\"1\" /></label>\n              <label>Currency<input id=\"verifyCurrency\" value=\"USD\" /></label>\n              <label>Context JSON<textarea id=\"verifyContext\" rows=\"4\">{\"campaign\":\"Holiday launch\"}</textarea></label>\n              <button class=\"btn\" id=\"verifyReceiptBtn\">Verify authority</button>\n              <label>Portable signed receipt\n                <select id=\"portableReceiptId\" style=\"width:100%;margin-top:6px;padding:10px 12px;border:1px solid #cfd9e6;border-radius:11px;background:white\"></select>\n              </label>\n              <button class=\"btn secondary\" id=\"downloadPortableReceiptBtn\">Download portable receipt</button>\n              <div id=\"verifyResult\" class=\"notice hidden\"></div>\n              <div class=\"error\" id=\"verifyError\"></div>\n            </div>\n          </div>\n\n          <div class=\"card\">\n            <div class=\"card-head\">\n              <div>\n                <h2>Delegate authority</h2>\n                <div class=\"muted\">Create a narrower child grant from an active receipt.</div>\n              </div>\n            </div>\n            <div class=\"form-grid\">\n              <label>Parent receipt\n                <select id=\"delegateReceiptId\" style=\"width:100%;margin-top:6px;padding:10px 12px;border:1px solid #cfd9e6;border-radius:11px;background:white\"></select>\n              </label>\n              <label>Delegate to agent<input id=\"delegateAgent\" value=\"assistant-agent\" /></label>\n              <label>Expires at<input id=\"delegateExpiresAt\" type=\"datetime-local\" /></label>\n              <button class=\"btn\" id=\"delegateReceiptBtn\">Delegate authority</button>\n              <div class=\"error\" id=\"delegateError\"></div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n    <section id=\"developer\" class=\"view\">\n      <div class=\"grid\">\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <div>\n              <h2>Developer environments</h2>\n              <div class=\"muted\">Separate credentials for development, staging, and production.</div>\n            </div>\n          </div>\n          <div id=\"environmentList\" class=\"list\"><div class=\"empty\">Loading…</div></div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <div>\n              <h2>Create API key</h2>\n              <div class=\"muted\">The raw key is shown once. AD NŪTUM stores only its SHA-256 hash.</div>\n            </div>\n          </div>\n          <div class=\"form-grid\">\n            <label>Environment\n              <select id=\"keyEnvironment\" style=\"width:100%;margin-top:6px;padding:10px 12px;border:1px solid #cfd9e6;border-radius:11px;background:white\"></select>\n            </label>\n            <label>Key name<input id=\"keyName\" value=\"Local development\" /></label>\n            <button class=\"btn\" id=\"createKeyBtn\">Create API key</button>\n            <div class=\"error\" id=\"keyError\"></div>\n            <div id=\"newKeyReveal\" class=\"secret-reveal hidden\">\n              <strong>Copy this key now. It will not be shown again.</strong>\n              <div class=\"muted\" id=\"newKeyCountdown\" style=\"margin-top:6px\">This reveal will clear automatically in 60 seconds.</div>\n              <div class=\"secret-value\" id=\"newKeyValue\" style=\"margin-top:10px\"></div>\n              <div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:10px\">\n                <button class=\"btn secondary small\" id=\"copyKeyBtn\">Copy key</button>\n                <button class=\"btn danger small\" id=\"dismissKeyBtn\">Dismiss key</button>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"grid\" style=\"margin-top:18px\">\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <div>\n              <h2>Human identities</h2>\n              <div class=\"muted\">Individual Control Plane credentials for governed actions.</div>\n            </div>\n          </div>\n          <div id=\"humanIdentityList\" class=\"list\"><div class=\"empty\">Loading…</div></div>\n          <div class=\"form-grid\" style=\"margin-top:14px\">\n            <label>Name<input id=\"humanIdentityName\" placeholder=\"Alex Owner\" /></label>\n            <label>Role\n              <select id=\"humanIdentityRole\" style=\"width:100%;margin-top:6px;padding:10px 12px;border:1px solid #cfd9e6;border-radius:11px;background:white\">\n                <option value=\"operator\">Operator</option>\n                <option value=\"owner\">Owner</option>\n              </select>\n            </label>\n            <button class=\"btn\" id=\"createHumanIdentityBtn\">Create human identity</button>\n            <div class=\"error\" id=\"humanIdentityError\"></div>\n            <div id=\"humanIdentityReveal\" class=\"secret-reveal hidden\">\n              <strong>Copy this token now. AD NŪTUM will not show it again.</strong>\n              <div class=\"muted\" id=\"humanIdentityCountdown\" style=\"margin-top:6px\">This reveal will clear automatically in 60 seconds.</div>\n              <div class=\"secret-value\" id=\"humanIdentityTokenValue\" style=\"margin-top:10px\"></div>\n              <div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:10px\">\n                <button class=\"btn secondary small\" id=\"copyHumanIdentityTokenBtn\">Copy token</button>\n                <button class=\"btn danger small\" id=\"dismissHumanIdentityTokenBtn\">Dismiss token</button>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <div>\n              <h2>Acting identity</h2>\n              <div class=\"muted\">Choose which authenticated human is requesting or deciding governed actions.</div>\n            </div>\n          </div>\n          <div class=\"form-grid\">\n            <label>Human identity token<input id=\"actingIdentityToken\" type=\"password\" autocomplete=\"off\" /></label>\n            <button class=\"btn secondary\" id=\"setActingIdentityBtn\">Use this identity</button>\n            <button class=\"btn danger\" id=\"stopActingIdentityBtn\">Stop acting as this identity</button>\n            <div id=\"actingIdentityStatus\" class=\"notice\">No human identity selected.</div>\n            <div class=\"error\" id=\"actingIdentityError\"></div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"grid\" style=\"margin-top:18px\">\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <div>\n              <h2>API keys</h2>\n              <div class=\"muted\">Project-scoped credentials. Revoked keys cannot authorize new actions.</div>\n            </div>\n          </div>\n          <div id=\"apiKeyList\" class=\"list\"><div class=\"empty\">Loading…</div></div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <div>\n              <h2>5-minute quickstart</h2>\n              <div class=\"muted\">Connect an agent without touching Supabase or Cloudflare.</div>\n            </div>\n          </div>\n          <div class=\"notice\">Install the SDK</div>\n          <div class=\"codebox\" id=\"installCode\">npm install @adnutum/sdk</div>\n          <div class=\"notice\">Create the client</div>\n          <div class=\"codebox\" id=\"clientCode\"></div>\n          <div class=\"notice\">Ask for authority</div>\n          <div class=\"codebox\" id=\"actionCode\"></div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"card-head\">\n            <div>\n              <h2>Signing trust</h2>\n              <div class=\"muted\">Public keys downstream systems can trust for receipt verification.</div>\n            </div>\n          </div>\n          <div id=\"signingKeyList\" class=\"list\"><div class=\"empty\">Loading…</div></div>\n        </div>\n      </div>\n    </section>\n\n  </main>\n</div>\n\n<div id=\"tokenModal\" class=\"modal-wrap\">\n  <div class=\"modal\">\n    <div class=\"kicker\">Operator access</div>\n    <h2>Unlock the Control Plane</h2>\n    <p class=\"muted\">Enter the Control Plane token configured for this demo Worker. The token is kept only in this browser session.</p>\n    <label>Control Plane token<input id=\"tokenInput\" type=\"password\" autocomplete=\"off\" /></label>\n    <div class=\"error\" id=\"tokenError\"></div>\n    <button class=\"btn\" id=\"unlockBtn\" style=\"width:100%;margin-top:16px\">Unlock</button>\n  </div>\n</div>\n\n<div id=\"requestModal\" class=\"modal-wrap hidden\">\n  <div class=\"modal\">\n    <div class=\"card-head\">\n      <div><div class=\"kicker\">Authorization request</div><h2 id=\"detailTitle\">Request</h2></div>\n      <button class=\"btn secondary small\" id=\"closeDetail\">Close</button>\n    </div>\n    <div id=\"detailBody\"></div>\n  </div>\n</div>\n\n<script>\n  const state = {\n    token: sessionStorage.getItem('adnutum_control_token') || '',\n    identityToken: sessionStorage.getItem('adnutum_human_identity_token') || '',\n    identity: null,\n    requests: [],\n    agents: [],\n    receipts: [],\n    keyRevealTimer: null,\n    humanIdentityRevealTimer: null\n  };\n\n  async function api(path, init = {}) {\n    const headers = {\n      'content-type': 'application/json',\n      'x-control-plane-token': state.token,\n      ...(state.identityToken ? { 'x-control-plane-identity-token': state.identityToken } : {}),\n      ...(init.headers || {})\n    };\n    const response = await fetch(path, { ...init, headers });\n    const text = await response.text();\n    const body = text ? JSON.parse(text) : null;\n    if (!response.ok) throw new Error(body?.error || body?.message || ('HTTP ' + response.status));\n    return body;\n  }\n\n  function pillFor(request) {\n    const approval = Array.isArray(request.approval_decisions) ? request.approval_decisions[0] : null;\n    if (approval?.decision === 'approved') return '<span class=\"pill approved\">approved</span>';\n    if (approval?.decision === 'rejected') return '<span class=\"pill rejected\">rejected</span>';\n    if (request.decision === 'approval_required') return '<span class=\"pill pending\">awaiting human</span>';\n    if (request.decision === 'allow') return '<span class=\"pill allowed\">allowed</span>';\n    return '<span class=\"pill denied\">denied</span>';\n  }\n\n  function requestCard(r) {\n    const payload = r.payload || {};\n    const amount = typeof payload.amount === 'number' ? '$' + payload.amount.toLocaleString() + ' · ' : '';\n    const agent = r.agent?.name || r.agent?.external_key || 'Unknown agent';\n    return `\n      <div class=\"request\">\n        <div>\n          <div class=\"request-title\">${amount}${escapeHtml(r.action)}</div>\n          <div class=\"request-meta\">${escapeHtml(agent)} · ${new Date(r.created_at).toLocaleString()}</div>\n        </div>\n        <div>${pillFor(r)}</div>\n        <div class=\"request-meta\">${escapeHtml(r.reason || '')}</div>\n        <div><button class=\"btn secondary small\" data-open-request=\"${r.id}\">Open</button></div>\n      </div>`;\n  }\n\n  function escapeHtml(value) {\n    return String(value ?? '').replace(/[&<>\"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#039;'}[ch]));\n  }\n\n  async function loadAll() {\n    const [reqData, agentData] = await Promise.all([api('/v1/requests?limit=100'), api('/v1/agents')]);\n    state.requests = reqData.requests || [];\n    state.agents = agentData.agents || [];\n\n    const pending = state.requests.filter(r => r.decision === 'approval_required' && !(r.approval_decisions || []).length).length;\n    const approved = state.requests.filter(r => (r.approval_decisions || [])[0]?.decision === 'approved').length;\n\n    document.querySelector('#statRequests').textContent = state.requests.length;\n    document.querySelector('#statPending').textContent = pending;\n    document.querySelector('#statApproved').textContent = approved;\n    document.querySelector('#statAgents').textContent = state.agents.length;\n\n    const cards = state.requests.length ? state.requests.map(requestCard).join('') : '<div class=\"empty\">No requests yet.</div>';\n    document.querySelector('#recentRequests').innerHTML = state.requests.length ? state.requests.slice(0,6).map(requestCard).join('') : '<div class=\"empty\">No requests yet.</div>';\n    document.querySelector('#allRequests').innerHTML = cards;\n\n    document.querySelector('#agentList').innerHTML = state.agents.length\n      ? state.agents.map(a => '<div class=\"request\"><div><div class=\"request-title\">' + escapeHtml(a.name) + '</div><div class=\"request-meta\">' + escapeHtml(a.external_key) + '</div></div><span class=\"pill allowed\">active</span></div>').join('')\n      : '<div class=\"empty\">No agents yet.</div>';\n\n    bindOpenButtons();\n  }\n\n  function bindOpenButtons() {\n    document.querySelectorAll('[data-open-request]').forEach(btn => {\n      btn.onclick = () => openRequest(btn.dataset.openRequest);\n    });\n  }\n\n  async function openRequest(id) {\n    const data = await api('/v1/requests/' + encodeURIComponent(id));\n    const r = data.request;\n    const p = r.payload || {};\n    const approval = data.approvals?.[0];\n\n    const amountText = typeof p.amount === 'number' ? '$' + p.amount.toLocaleString() : '—';\n    const target =\n      p.context?.customer ||\n      p.context?.campaign ||\n      p.context?.vendor ||\n      p.context?.channel ||\n      p.context?.record ||\n      '—';\n\n    document.querySelector('#detailTitle').textContent =\n      typeof p.amount === 'number'\n        ? '$' + p.amount.toLocaleString() + ' · ' + r.action\n        : r.action;\n\n    document.querySelector('#detailBody').innerHTML = `\n      <div class=\"notice\">\n        <strong>Agent:</strong> ${escapeHtml(r.agent?.name || r.agent?.external_key || 'Unknown')}<br>\n        <strong>Action:</strong> ${escapeHtml(r.action)}<br>\n        <strong>Amount:</strong> ${escapeHtml(amountText)}<br>\n        <strong>Target:</strong> ${escapeHtml(target)}<br>\n        <strong>Reason:</strong> ${escapeHtml(p.context?.reason || '—')}<br>\n        <strong>Policy decision:</strong> ${escapeHtml(r.decision)}<br>\n        <strong>Required approver:</strong> ${escapeHtml(r.required_approver || 'none')}<br>\n        <strong>Requested by:</strong> ${escapeHtml(r.requester ? (r.requester.name + ' · ' + r.requester.role) : 'legacy / unbound')}\n      </div>\n      <h3>Audit trail</h3>\n      <ul class=\"timeline\">${(data.events || []).map(e =>\n        '<li><strong>' + escapeHtml(e.event_type) + '</strong>' +\n        new Date(e.created_at).toLocaleString() + '</li>'\n      ).join('')}</ul>\n      ${r.decision === 'approval_required' && !approval ? `\n        <label style=\"display:block;margin-top:16px\">\n          Decision note\n          <textarea id=\"decisionNote\" rows=\"2\">Reviewed in AD NŪTUM Control Plane.</textarea>\n        </label>\n        <div class=\"split\" style=\"margin-top:12px\">\n          <button class=\"btn danger\" id=\"rejectDetail\">Reject</button>\n          <button class=\"btn success\" id=\"approveDetail\">Approve</button>\n        </div>\n        <div class=\"error\" id=\"decisionError\"></div>\n      ` : '<div class=\"notice\" style=\"margin-top:16px\"><strong>Final human decision:</strong> ' +\n        escapeHtml(approval?.decision || 'No human decision required') + '</div>'}\n    `;\n\n    document.querySelector('#requestModal').classList.remove('hidden');\n    const approve = document.querySelector('#approveDetail');\n    const reject = document.querySelector('#rejectDetail');\n    if (approve) approve.onclick = () => decide(id, 'approved');\n    if (reject) reject.onclick = () => decide(id, 'rejected');\n  }\n\n  async function decide(id, decision) {\n    const note = document.querySelector('#decisionNote')?.value || '';\n    const err = document.querySelector('#decisionError');\n    if (err) err.textContent = '';\n    try {\n      await api('/v1/requests/' + encodeURIComponent(id) + '/decision', {\n        method: 'POST',\n        body: JSON.stringify({ decision, note })\n      });\n      document.querySelector('#requestModal').classList.add('hidden');\n      await loadAll();\n    } catch (e) {\n      const code = e?.message || 'decision_failed';\n      const messages = {\n        owner_identity_required: 'Blocked: an Owner identity is required for this decision.',\n        separation_of_duties_violation: 'Blocked: the requester cannot approve their own governed action.',\n        human_identity_required: 'Blocked: select an authenticated human identity before deciding this request.'\n      };\n      if (err) err.textContent = messages[code] || ('Blocked: ' + code);\n    }\n  }\n\n  async function loadPolicy() {\n    const data = await api('/v1/policies/refund_customer');\n    document.querySelector('#automaticBelow').value = data.rule.automaticBelow;\n    document.querySelector('#managerThrough').value = data.rule.managerThrough;\n  }\n\n  document.querySelectorAll('nav button').forEach(btn => {\n    btn.onclick = async () => {\n      document.querySelectorAll('nav button').forEach(x => x.classList.remove('active'));\n      btn.classList.add('active');\n      document.querySelectorAll('.view').forEach(x => x.classList.remove('active'));\n      document.querySelector('#' + btn.dataset.view).classList.add('active');\n      const labels = {\n        overview: ['Authorization overview','See what agents asked to do, what policy decided, and where human judgment entered.'],\n        requests: ['Authorization requests','Every consequential request and its current state.'],\n        agents: ['Agents','Stable identities that ask AD NŪTUM for authority.'],\n        policy: ['Policy','Define the boundary between automatic action and human judgment.'],\n        receipts: ['Authority receipts','See active, delegated, expired, and revoked grants of agent authority.'],\n        developer: ['Developer','Create environment-scoped credentials and connect external agents.']\n      };\n      document.querySelector('#pageTitle').textContent = labels[btn.dataset.view][0];\n      document.querySelector('#pageSub').textContent = labels[btn.dataset.view][1];\n      if (btn.dataset.view === 'policy') await loadPolicy();\n      if (btn.dataset.view === 'receipts') await loadReceipts();\n      if (btn.dataset.view === 'developer') await loadDeveloper();\n    };\n  });\n\n  function configureAuthorityLab() {\n    const action = document.querySelector('#testAction').value;\n    const amountField = document.querySelector('#amountField');\n    const subjectField = document.querySelector('#subjectField');\n    const vendorField = document.querySelector('#vendorField');\n    const sensitiveField = document.querySelector('#sensitiveField');\n    const scopeField = document.querySelector('#scopeField');\n    const subjectLabel = document.querySelector('#subjectLabel');\n    const amount = document.querySelector('#testAmount');\n    const subject = document.querySelector('#testSubject');\n    const agent = document.querySelector('#testAgent');\n    const reason = document.querySelector('#testReason');\n\n    amountField.classList.toggle('hidden', !['refund_customer','increase_ad_budget','pay_invoice'].includes(action));\n    subjectField.classList.toggle('hidden', action === 'deploy_production');\n    vendorField.classList.toggle('hidden', action !== 'pay_invoice');\n    sensitiveField.classList.toggle('hidden', action !== 'publish_content');\n    scopeField.classList.toggle('hidden', action !== 'delete_record');\n\n    const presets = {\n      refund_customer: ['Customer', 4800, 'ABC Manufacturing', 'finance-agent', 'Duplicate payment detected'],\n      increase_ad_budget: ['Campaign', 250, 'Holiday launch', 'marketing-agent', 'Campaign performance supports a budget increase'],\n      pay_invoice: ['Vendor', 1200, 'Northstar Supplies', 'finance-agent', 'Invoice matched to purchase order'],\n      publish_content: ['Channel', 0, 'Instagram', 'publishing-agent', 'Scheduled public announcement'],\n      deploy_production: ['Target', 0, '', 'developer-agent', 'Release candidate passed automated tests'],\n      delete_record: ['Record', 0, 'customer_1042', 'data-agent', 'Duplicate test record']\n    };\n    const preset = presets[action];\n    subjectLabel.textContent = preset[0];\n    amount.value = preset[1] || '';\n    subject.value = preset[2];\n    agent.value = preset[3];\n    reason.value = preset[4];\n  }\n\n  document.querySelector('#testAction').addEventListener('change', configureAuthorityLab);\n  configureAuthorityLab();\n\n  document.querySelector('#createRequestBtn').onclick = async () => {\n    const err = document.querySelector('#createError'); err.textContent = '';\n    try {\n      const action = document.querySelector('#testAction').value;\n      const amountValue = Number(document.querySelector('#testAmount').value);\n      const subject = document.querySelector('#testSubject').value.trim();\n      const context = { reason: document.querySelector('#testReason').value.trim() };\n\n      if (action === 'refund_customer') context.customer = subject;\n      if (action === 'increase_ad_budget') context.campaign = subject;\n      if (action === 'pay_invoice') {\n        context.vendor = subject;\n        context.vendorApproved = document.querySelector('#testVendorApproved').checked;\n      }\n      if (action === 'publish_content') {\n        context.channel = subject;\n        context.sensitive = document.querySelector('#testSensitive').checked;\n      }\n      if (action === 'delete_record') {\n        context.record = subject;\n        context.scope = document.querySelector('#testScope').value;\n      }\n\n      const body = {\n        agentId: document.querySelector('#testAgent').value.trim(),\n        action,\n        currency: 'USD',\n        context\n      };\n      if (['refund_customer','increase_ad_budget','pay_invoice'].includes(action)) body.amount = amountValue;\n\n      await api('/v1/authorize', { method: 'POST', body: JSON.stringify(body) });\n      await loadAll();\n    } catch (e) { err.textContent = e.message; }\n  };\n\n  document.querySelector('#addAgentBtn').onclick = async () => {\n    const err = document.querySelector('#agentError'); err.textContent = '';\n    try {\n      await api('/v1/agents', {\n        method: 'POST',\n        body: JSON.stringify({\n          externalKey: document.querySelector('#agentKey').value.trim(),\n          name: document.querySelector('#agentName').value.trim()\n        })\n      });\n      document.querySelector('#agentKey').value = '';\n      document.querySelector('#agentName').value = '';\n      await loadAll();\n    } catch (e) { err.textContent = e.message; }\n  };\n\n  document.querySelector('#savePolicyBtn').onclick = async () => {\n    const err = document.querySelector('#policyError'); err.textContent = '';\n    try {\n      await api('/v1/policies/refund_customer', {\n        method: 'PUT',\n        body: JSON.stringify({\n          automaticBelow: Number(document.querySelector('#automaticBelow').value),\n          managerThrough: Number(document.querySelector('#managerThrough').value)\n        })\n      });\n      await loadPolicy();\n      err.style.color = '#087443';\n      err.textContent = 'Policy saved.';\n      setTimeout(() => { err.textContent=''; err.style.color=''; }, 1800);\n    } catch (e) { err.textContent = e.message; }\n  };\n\n\n  function receiptPill(state) {\n    if (state === 'active') return '<span class=\"pill allowed\">active</span>';\n    if (state === 'expired') return '<span class=\"pill pending\">expired</span>';\n    return '<span class=\"pill rejected\">revoked</span>';\n  }\n\n  async function loadReceipts() {\n    const data = await api('/v1/receipts');\n    const receipts = data.receipts || [];\n    const list = document.querySelector('#receiptList');\n    list.innerHTML = receipts.length ? receipts.map(r => {\n      const agent = r.agent?.name || r.agent?.external_key || 'Unknown agent';\n      const delegated = r.parent_receipt_id ? ' · delegated' : '';\n      const envName = r.environment?.name || r.environment?.slug || 'Unknown environment';\n      return '<div class=\"key-row\"><div><div class=\"request-title\">' +\n        escapeHtml(r.action) + '</div><div class=\"request-meta\">' +\n        escapeHtml(agent) + ' · ' + escapeHtml(envName) + delegated +\n        ' · expires ' + new Date(r.expires_at).toLocaleString() +\n        '</div><div class=\"request-meta\">issued by ' + escapeHtml(r.issued_by) +\n        (r.signature ? ' · signed ' + escapeHtml(r.signature_algorithm || 'ES256') + ' · ' + escapeHtml(r.signing_key_id || 'key') : ' · unsigned') +\n        '</div></div>' +\n        '<div style=\"display:flex;gap:8px;align-items:center\">' +\n        receiptPill(r.state) +\n        (r.state === 'active' ? '<button class=\"btn danger small\" data-revoke-receipt=\"' + r.id + '\">Revoke</button>' : '') +\n        '</div></div>';\n    }).join('') : '<div class=\"empty\">No authority receipts yet.</div>';\n\n    state.receipts = receipts;\n    const active = receipts.filter(r => r.state === 'active');\n\n    function receiptLabel(r) {\n      const scope = r.scope || {};\n      const amountPrefix =\n        typeof scope.amount === 'number'\n          ? '$' + scope.amount.toLocaleString() + ' · '\n          : '';\n      const agentName = r.agent?.name || r.agent?.external_key || 'agent';\n      const issuedTime = new Date(r.issued_at).toLocaleTimeString([], {\n        hour: 'numeric',\n        minute: '2-digit'\n      });\n      return amountPrefix + r.action + ' · ' + agentName + ' · ' + issuedTime;\n    }\n\n    const activeOptions = active.map(r =>\n      '<option value=\"' + r.id + '\">' + escapeHtml(receiptLabel(r)) + '</option>'\n    ).join('');\n\n    document.querySelector('#delegateReceiptId').innerHTML = activeOptions;\n    document.querySelector('#verifyReceiptId').innerHTML = activeOptions;\n\n    const signed = receipts.filter(r => r.signature && r.signed_payload);\n    const signedOptions = signed.map(r =>\n      '<option value=\"' + r.id + '\">' + escapeHtml(receiptLabel(r)) + ' · ' + escapeHtml(r.state) + '</option>'\n    ).join('');\n    document.querySelector('#portableReceiptId').innerHTML = signedOptions;\n\n    populateVerificationFromSelectedReceipt();\n\n    document.querySelectorAll('[data-revoke-receipt]').forEach(btn => {\n      btn.onclick = async () => {\n        await api('/v1/receipts/' + encodeURIComponent(btn.dataset.revokeReceipt) + '/revoke', {\n          method: 'POST',\n          body: JSON.stringify({ revokedBy: 'control-plane-owner', reason: 'Revoked from Control Plane.' })\n        });\n        await loadReceipts();\n      };\n    });\n  }\n\n  function populateVerificationFromSelectedReceipt() {\n    const select = document.querySelector('#verifyReceiptId');\n    const receipt = state.receipts.find(r => r.id === select.value);\n    if (!receipt) return;\n\n    const scope = receipt.scope || {};\n    document.querySelector('#verifyAgent').value = receipt.agent?.external_key || receipt.agent?.name || '';\n    document.querySelector('#verifyAction').value = receipt.action || '';\n    document.querySelector('#verifyAmount').value = typeof scope.amount === 'number' ? scope.amount : '';\n    document.querySelector('#verifyCurrency').value = scope.currency || '';\n    document.querySelector('#verifyContext').value = JSON.stringify(scope.context || {}, null, 2);\n\n    const resultBox = document.querySelector('#verifyResult');\n    const err = document.querySelector('#verifyError');\n    resultBox.classList.add('hidden');\n    resultBox.textContent = '';\n    err.textContent = '';\n  }\n\n  document.querySelector('#verifyReceiptId').addEventListener('change', populateVerificationFromSelectedReceipt);\n\n  document.querySelector('#downloadPortableReceiptBtn').onclick = () => {\n    const select = document.querySelector('#portableReceiptId');\n    const receipt = state.receipts.find(r => r.id === select.value);\n    const err = document.querySelector('#verifyError');\n    err.textContent = '';\n    if (!receipt) {\n      err.textContent = 'Choose a signed receipt first.';\n      return;\n    }\n    if (!receipt.signature || !receipt.signed_payload) {\n      err.textContent = 'This receipt is unsigned and cannot be verified offline.';\n      return;\n    }\n\n    const blob = new Blob([JSON.stringify(receipt, null, 2)], { type: 'application/json' });\n    const url = URL.createObjectURL(blob);\n    const link = document.createElement('a');\n    link.href = url;\n    link.download = 'adnutum-portable-receipt.json';\n    document.body.appendChild(link);\n    link.click();\n    link.remove();\n    URL.revokeObjectURL(url);\n\n    const btn = document.querySelector('#downloadPortableReceiptBtn');\n    btn.textContent = 'Receipt downloaded';\n    setTimeout(() => btn.textContent = 'Download portable receipt', 1500);\n  };\n\n  document.querySelector('#verifyReceiptBtn').onclick = async () => {\n    const err = document.querySelector('#verifyError');\n    const resultBox = document.querySelector('#verifyResult');\n    err.textContent = '';\n    resultBox.classList.add('hidden');\n    resultBox.textContent = '';\n    try {\n      let context = {};\n      const rawContext = document.querySelector('#verifyContext').value.trim();\n      if (rawContext) context = JSON.parse(rawContext);\n\n      const result = await api('/v1/verify', {\n        method: 'POST',\n        body: JSON.stringify({\n          receiptId: document.querySelector('#verifyReceiptId').value,\n          agentId: document.querySelector('#verifyAgent').value.trim(),\n          action: document.querySelector('#verifyAction').value.trim(),\n          amount: Number(document.querySelector('#verifyAmount').value),\n          currency: document.querySelector('#verifyCurrency').value.trim(),\n          context\n        })\n      });\n\n      resultBox.textContent = result.valid\n        ? 'VALID · Authority verified · expires ' + new Date(result.expiresAt).toLocaleString()\n        : 'INVALID · ' + result.reason;\n      resultBox.classList.remove('hidden');\n    } catch (e) {\n      err.textContent = e.message;\n    }\n  };\n\n  document.querySelector('#refreshReceiptsBtn').onclick = loadReceipts;\n\n  document.querySelector('#delegateReceiptBtn').onclick = async () => {\n    const err = document.querySelector('#delegateError'); err.textContent = '';\n    try {\n      const parent = document.querySelector('#delegateReceiptId').value;\n      const agent = document.querySelector('#delegateAgent').value.trim();\n      if (!parent || !agent) throw new Error('Choose an active receipt and enter a delegate agent.');\n      const localExpiry = document.querySelector('#delegateExpiresAt').value;\n      const body = {\n        delegateToAgentId: agent,\n        issuedBy: 'control-plane-owner'\n      };\n      if (localExpiry) body.expiresAt = new Date(localExpiry).toISOString();\n      await api('/v1/receipts/' + encodeURIComponent(parent) + '/delegate', {\n        method: 'POST',\n        body: JSON.stringify(body)\n      });\n      document.querySelector('#delegateAgent').value = '';\n      document.querySelector('#delegateExpiresAt').value = '';\n      await loadReceipts();\n    } catch (e) {\n      err.textContent = e.message;\n    }\n  };\n\n  async function loadDeveloper() {\n    const [envData, keyData, quickstart, trustData, signingKeyData, humanData] = await Promise.all([\n      api('/v1/developer/environments'),\n      api('/v1/developer/api-keys'),\n      api('/v1/developer/quickstart'),\n      api('/.well-known/jwks.json'),\n      api('/v1/developer/signing-keys'),\n      api('/v1/developer/human-identities')\n    ]);\n\n    const environments = envData.environments || [];\n    document.querySelector('#environmentList').innerHTML = environments.map(e =>\n      '<div class=\"key-row\"><div><div class=\"request-title\">' + escapeHtml(e.name) + '</div><div class=\"request-meta\">' + escapeHtml(e.slug) + (e.is_default ? ' · default' : '') + '</div></div><span class=\"pill allowed\">ready</span></div>'\n    ).join('');\n\n    document.querySelector('#keyEnvironment').innerHTML = environments.map(e =>\n      '<option value=\"' + e.id + '\">' + escapeHtml(e.name) + '</option>'\n    ).join('');\n\n    const humans = humanData.identities || [];\n    document.querySelector('#humanIdentityList').innerHTML = humans.length ? humans.map(h => {\n      const revoked = Boolean(h.revoked_at);\n      const lifecycle = (h.last_used_at ? ' · last used ' + new Date(h.last_used_at).toLocaleString() : ' · never used') +\n        (h.token_rotated_at ? ' · rotated ' + new Date(h.token_rotated_at).toLocaleString() : '') +\n        (h.revoked_at ? ' · revoked ' + new Date(h.revoked_at).toLocaleString() : '');\n      const reason = h.revocation_reason\n        ? '<div class=\"request-meta\">reason: ' + escapeHtml(h.revocation_reason) + '</div>'\n        : '';\n      const actions = revoked\n        ? '<span class=\"pill rejected\">revoked</span>'\n        : '<div style=\"display:flex;gap:8px;align-items:center;flex-wrap:wrap\">' +\n          '<span class=\"pill allowed\">' + escapeHtml(h.role) + '</span>' +\n          '<button class=\"btn secondary small\" data-rotate-human=\"' + h.id + '\">Rotate token</button>' +\n          '<button class=\"btn danger small\" data-revoke-human=\"' + h.id + '\" data-human-name=\"' + escapeHtml(h.name) + '\">Revoke identity</button>' +\n          '</div>';\n      return '<div class=\"key-row\"><div><div class=\"request-title\">' + escapeHtml(h.name) +\n        '</div><div class=\"request-meta\">' + escapeHtml(h.role) + ' · ' +\n        escapeHtml(h.token_prefix) + '••••' + escapeHtml(h.last4) + lifecycle +\n        '</div>' + reason + '</div>' + actions + '</div>';\n    }).join('') : '<div class=\"empty\">No human identities yet.</div>';\n\n    document.querySelectorAll('[data-rotate-human]').forEach(btn => {\n      btn.onclick = async () => {\n        const identityId = btn.dataset.rotateHuman;\n        const confirmed = window.confirm('Rotate this human identity token? The previous token will stop working immediately.');\n        if (!confirmed) return;\n        try {\n          const result = await api('/v1/developer/human-identities/' + encodeURIComponent(identityId) + '/rotate', {\n            method: 'POST',\n            body: JSON.stringify({})\n          });\n          if (state.identity?.id === identityId) {\n            state.identityToken = '';\n            state.identity = null;\n            sessionStorage.removeItem('adnutum_human_identity_token');\n            document.querySelector('#actingIdentityToken').value = '';\n            document.querySelector('#actingIdentityStatus').textContent = 'No human identity selected.';\n          }\n          showHumanIdentityReveal(result.token);\n          await loadDeveloper();\n        } catch (e) {\n          window.alert('Rotation blocked: ' + e.message);\n        }\n      };\n    });\n\n    document.querySelectorAll('[data-revoke-human]').forEach(btn => {\n      btn.onclick = async () => {\n        const identityId = btn.dataset.revokeHuman;\n        const identityName = btn.dataset.humanName || 'this identity';\n        const reason = window.prompt('Enter the reason for revoking ' + identityName + ':');\n        if (!reason || !reason.trim()) return;\n        const confirmed = window.confirm('Revoke ' + identityName + '? Its token will stop working immediately.');\n        if (!confirmed) return;\n        try {\n          await api('/v1/developer/human-identities/' + encodeURIComponent(identityId) + '/revoke', {\n            method: 'POST',\n            body: JSON.stringify({ reason: reason.trim() })\n          });\n          if (state.identity?.id === identityId) {\n            state.identityToken = '';\n            state.identity = null;\n            sessionStorage.removeItem('adnutum_human_identity_token');\n            document.querySelector('#actingIdentityToken').value = '';\n            document.querySelector('#actingIdentityStatus').textContent = 'No human identity selected.';\n          }\n          await loadDeveloper();\n        } catch (e) {\n          const messages = {\n            last_active_owner_cannot_be_revoked: 'Blocked: AD NŪTUM will not revoke the final active Owner.',\n            human_identity_already_revoked: 'This human identity is already revoked.'\n          };\n          window.alert(messages[e.message] || ('Revocation blocked: ' + e.message));\n        }\n      };\n    });\n\n    const keys = keyData.apiKeys || [];\n    document.querySelector('#apiKeyList').innerHTML = keys.length ? keys.map(k => {\n      const revoked = Boolean(k.revoked_at);\n      const envName = k.environment?.name || k.environment?.slug || 'Unknown environment';\n      return '<div class=\"key-row\"><div><div class=\"request-title\">' + escapeHtml(k.name) + '</div><div class=\"request-meta\">' +\n        escapeHtml(envName) + ' · ' + escapeHtml(k.key_prefix) + '••••' + escapeHtml(k.last4) +\n        (k.last_used_at ? ' · last used ' + new Date(k.last_used_at).toLocaleString() : ' · never used') +\n        '</div></div>' +\n        (revoked ? '<span class=\"pill rejected\">revoked</span>' : '<button class=\"btn danger small\" data-revoke-key=\"' + k.id + '\">Revoke</button>') +\n        '</div>';\n    }).join('') : '<div class=\"empty\">No API keys yet.</div>';\n\n    document.querySelectorAll('[data-revoke-key]').forEach(btn => {\n      btn.onclick = async () => {\n        await api('/v1/developer/api-keys/' + encodeURIComponent(btn.dataset.revokeKey), { method: 'DELETE' });\n        await loadDeveloper();\n      };\n    });\n\n    document.querySelector('#installCode').textContent = quickstart.install;\n    document.querySelector('#clientCode').textContent = quickstart.example.javascript;\n    document.querySelector('#actionCode').textContent = quickstart.example.action;\n\n    const signingKeys = signingKeyData.signingKeys || [];\n    document.querySelector('#signingKeyList').innerHTML = signingKeys.length ? signingKeys.map(k => {\n      const statusClass = k.status === 'active' ? 'allowed' : (k.status === 'retired' ? 'pending' : 'rejected');\n      const lifecycle = ' · activated ' + new Date(k.activated_at).toLocaleString() +\n        (k.retired_at ? ' · retired ' + new Date(k.retired_at).toLocaleString() : '') +\n        (k.revoked_at ? ' · revoked ' + new Date(k.revoked_at).toLocaleString() : '');\n      const revokeButton = k.status !== 'revoked'\n        ? '<button class=\"btn danger small\" data-revoke-signing-key=\"' + escapeHtml(k.id) + '\" data-key-status=\"' + escapeHtml(k.status) + '\">Request revocation</button>'\n        : '';\n      const reason = k.revocation_reason\n        ? '<div class=\"request-meta\">reason: ' + escapeHtml(k.revocation_reason) + '</div>'\n        : '';\n      return '<div class=\"key-row\"><div><div class=\"request-title\">' + escapeHtml(k.id) +\n        '</div><div class=\"request-meta\">' + escapeHtml(k.algorithm) + lifecycle +\n        '</div>' + reason + '</div><div style=\"display:flex;gap:8px;align-items:center\">' +\n        '<span class=\"pill ' + statusClass + '\">' + escapeHtml(k.status) + '</span>' +\n        revokeButton + '</div></div>';\n    }).join('') : '<div class=\"empty\">No signing keys registered yet.</div>';\n\n    document.querySelectorAll('[data-revoke-signing-key]').forEach(btn => {\n      btn.onclick = async () => {\n        const keyId = btn.dataset.revokeSigningKey;\n        const status = btn.dataset.keyStatus;\n        const warning = status === 'active'\n          ? 'This is the ACTIVE signing key. Requesting revocation will require owner approval before trust is withdrawn. Enter the emergency revocation reason:'\n          : 'Enter the emergency revocation reason. Owner approval will be required before trust is withdrawn:';\n        const reason = window.prompt(warning);\n        if (!reason || !reason.trim()) return;\n\n        const confirmed = window.confirm(\n          'Request owner approval to revoke trust for ' + keyId + '? The key will remain unchanged until approval.'\n        );\n        if (!confirmed) return;\n\n        const result = await api('/v1/developer/signing-keys/' + encodeURIComponent(keyId) + '/revoke', {\n          method: 'POST',\n          body: JSON.stringify({\n            reason: reason.trim()\n          })\n        });\n\n        window.alert('Revocation requested. No trust change has occurred yet. Request ' + result.requestId + ' is awaiting owner approval.');\n        await loadAll();\n        await loadDeveloper();\n      };\n    });\n  }\n\n  async function refreshActingIdentity() {\n    const status = document.querySelector('#actingIdentityStatus');\n    const err = document.querySelector('#actingIdentityError');\n    err.textContent = '';\n    if (!state.identityToken) {\n      state.identity = null;\n      status.textContent = 'No human identity selected.';\n      return;\n    }\n    try {\n      const data = await api('/v1/developer/human-identities/me');\n      state.identity = data.identity;\n      status.textContent = 'Acting as ' + state.identity.name + ' · ' + state.identity.role;\n    } catch (e) {\n      state.identity = null;\n      if (e.message === 'human_identity_revoked') {\n        status.textContent = 'Identity credential revoked.';\n        err.textContent = 'This human identity token has been revoked and can no longer act.';\n      } else {\n        status.textContent = 'No valid human identity selected.';\n        err.textContent = e.message;\n      }\n    }\n  }\n\n  function clearHumanIdentityReveal(message = '') {\n    if (state.humanIdentityRevealTimer) {\n      clearInterval(state.humanIdentityRevealTimer);\n      state.humanIdentityRevealTimer = null;\n    }\n    const reveal = document.querySelector('#humanIdentityReveal');\n    const value = document.querySelector('#humanIdentityTokenValue');\n    const countdown = document.querySelector('#humanIdentityCountdown');\n    const copyBtn = document.querySelector('#copyHumanIdentityTokenBtn');\n    if (value) {\n      value.textContent = '';\n      value.dataset.rawToken = '';\n    }\n    if (copyBtn) copyBtn.disabled = false;\n    if (message && countdown) {\n      countdown.textContent = message;\n      reveal?.classList.remove('hidden');\n      setTimeout(() => reveal?.classList.add('hidden'), 1800);\n    } else {\n      reveal?.classList.add('hidden');\n    }\n  }\n\n  function showHumanIdentityReveal(token) {\n    clearHumanIdentityReveal();\n    const reveal = document.querySelector('#humanIdentityReveal');\n    const value = document.querySelector('#humanIdentityTokenValue');\n    const countdown = document.querySelector('#humanIdentityCountdown');\n    if (!reveal || !value || !countdown) return;\n\n    value.textContent = token;\n    value.dataset.rawToken = token;\n    reveal.classList.remove('hidden');\n\n    let remaining = 60;\n    countdown.textContent = 'This reveal will clear automatically in 60 seconds.';\n    state.humanIdentityRevealTimer = setInterval(() => {\n      remaining -= 1;\n      if (remaining <= 0) {\n        clearHumanIdentityReveal();\n        return;\n      }\n      countdown.textContent = 'This reveal will clear automatically in ' + remaining + ' seconds.';\n    }, 1000);\n  }\n\n  const createHumanIdentityBtn = document.querySelector('#createHumanIdentityBtn');\n  if (createHumanIdentityBtn) createHumanIdentityBtn.onclick = async () => {\n    const err = document.querySelector('#humanIdentityError');\n    err.textContent = '';\n    clearHumanIdentityReveal();\n    try {\n      const created = await api('/v1/developer/human-identities', {\n        method: 'POST',\n        body: JSON.stringify({\n          name: document.querySelector('#humanIdentityName').value.trim(),\n          role: document.querySelector('#humanIdentityRole').value\n        })\n      });\n      showHumanIdentityReveal(created.token);\n      await loadDeveloper();\n    } catch (e) {\n      err.textContent = e.message;\n    }\n  };\n\n  const copyHumanIdentityTokenBtn = document.querySelector('#copyHumanIdentityTokenBtn');\n  if (copyHumanIdentityTokenBtn) copyHumanIdentityTokenBtn.onclick = async () => {\n    const value = document.querySelector('#humanIdentityTokenValue');\n    const token = value?.dataset.rawToken || '';\n    if (!token) return;\n    await navigator.clipboard.writeText(token);\n    clearHumanIdentityReveal('Copied. Raw token cleared from this screen.');\n  };\n\n  const dismissHumanIdentityTokenBtn = document.querySelector('#dismissHumanIdentityTokenBtn');\n  if (dismissHumanIdentityTokenBtn) dismissHumanIdentityTokenBtn.onclick = () => clearHumanIdentityReveal();\n\n  const setActingIdentityBtn = document.querySelector('#setActingIdentityBtn');\n  if (setActingIdentityBtn) setActingIdentityBtn.onclick = async () => {\n    state.identityToken = document.querySelector('#actingIdentityToken').value.trim();\n    if (state.identityToken) sessionStorage.setItem('adnutum_human_identity_token', state.identityToken);\n    else sessionStorage.removeItem('adnutum_human_identity_token');\n    await refreshActingIdentity();\n  };\n\n  const stopActingIdentityBtn = document.querySelector('#stopActingIdentityBtn');\n  if (stopActingIdentityBtn) stopActingIdentityBtn.onclick = () => {\n    state.identityToken = '';\n    state.identity = null;\n    sessionStorage.removeItem('adnutum_human_identity_token');\n    document.querySelector('#actingIdentityToken').value = '';\n    document.querySelector('#actingIdentityStatus').textContent = 'No human identity selected.';\n    document.querySelector('#actingIdentityError').textContent = '';\n  };\n\n  const createKeyBtn = document.querySelector('#createKeyBtn');\n  if (createKeyBtn) createKeyBtn.onclick = async () => {\n    const err = document.querySelector('#keyError'); err.textContent = '';\n    try {\n      const created = await api('/v1/developer/api-keys', {\n        method: 'POST',\n        body: JSON.stringify({\n          environmentId: document.querySelector('#keyEnvironment').value,\n          name: document.querySelector('#keyName').value.trim()\n        })\n      });\n      showOneTimeKey(created.key);\n      await loadDeveloper();\n    } catch (e) { err.textContent = e.message; }\n  };\n\n  function clearOneTimeKey() {\n    if (state.keyRevealTimer) {\n      clearInterval(state.keyRevealTimer);\n      state.keyRevealTimer = null;\n    }\n    const value = document.querySelector('#newKeyValue');\n    const reveal = document.querySelector('#newKeyReveal');\n    const countdown = document.querySelector('#newKeyCountdown');\n    if (value) value.textContent = '';\n    if (countdown) countdown.textContent = 'This key reveal has been cleared.';\n    if (reveal) reveal.classList.add('hidden');\n  }\n\n  function showOneTimeKey(key) {\n    clearOneTimeKey();\n    const value = document.querySelector('#newKeyValue');\n    const reveal = document.querySelector('#newKeyReveal');\n    const countdown = document.querySelector('#newKeyCountdown');\n    if (!value || !reveal || !countdown) return;\n\n    value.textContent = key;\n    reveal.classList.remove('hidden');\n\n    let remaining = 60;\n    countdown.textContent = 'This reveal will clear automatically in 60 seconds.';\n    state.keyRevealTimer = setInterval(() => {\n      remaining -= 1;\n      if (remaining <= 0) {\n        clearOneTimeKey();\n        return;\n      }\n      countdown.textContent = 'This reveal will clear automatically in ' + remaining + ' seconds.';\n    }, 1000);\n  }\n\n  const copyKeyBtn = document.querySelector('#copyKeyBtn');\n  if (copyKeyBtn) copyKeyBtn.onclick = async () => {\n    const value = document.querySelector('#newKeyValue')?.textContent || '';\n    if (!value) return;\n    await navigator.clipboard.writeText(value);\n    copyKeyBtn.textContent = 'Copied';\n    setTimeout(() => copyKeyBtn.textContent = 'Copy key', 1200);\n  };\n\n  const dismissKeyBtn = document.querySelector('#dismissKeyBtn');\n  if (dismissKeyBtn) dismissKeyBtn.onclick = clearOneTimeKey;\n\n  document.querySelector('#refreshBtn').onclick = loadAll;\n  document.querySelector('#closeDetail').onclick = () => document.querySelector('#requestModal').classList.add('hidden');\n\n  async function unlock() {\n    const token = document.querySelector('#tokenInput').value.trim();\n    state.token = token;\n    try {\n      await loadAll();\n      sessionStorage.setItem('adnutum_control_token', token);\n      document.querySelector('#tokenModal').classList.add('hidden');\n      document.querySelector('#tokenError').textContent = '';\n      if (state.identityToken) await refreshActingIdentity();\n    } catch (e) {\n      state.token = '';\n      document.querySelector('#tokenError').textContent = 'Unlock failed: ' + (e?.message || 'unknown error');\n    }\n  }\n\n  document.querySelector('#unlockBtn').onclick = unlock;\n  document.querySelector('#tokenInput').addEventListener('keydown', e => { if (e.key === 'Enter') unlock(); });\n\n  if (state.token) {\n    loadAll().then(async () => {\n      document.querySelector('#tokenModal').classList.add('hidden');\n      if (state.identityToken) await refreshActingIdentity();\n    }).catch(() => sessionStorage.removeItem('adnutum_control_token'));\n  }\n</script>\n</body>\n</html>";
